import{_ as r,C as a,c as n,o as i,a3 as t,G as s}from"./chunks/framework.Dokpd4od.js";const w=JSON.parse('{"title":"Search, filter and group records","description":"","frontmatter":{},"headers":[],"relativePath":"master/getting-started/search-filter-group.md","filePath":"master/getting-started/search-filter-group.md","lastUpdated":1791902625000}'),l={name:"master/getting-started/search-filter-group.md"};function h(g,e,d,c,u,m){const o=a("ImagePopup");return i(),n("div",null,[e[0]||(e[0]=t('<h1 id="search-filter-and-group-records" tabindex="-1">Search, filter and group records <a class="header-anchor" href="#search-filter-and-group-records" aria-label="Permalink to &quot;Search, filter and group records&quot;">​</a></h1><p>Most pages in Aureus show records in a list. When the list grows, you need a way to find the right records fast. You can search the whole system from anywhere, and use the tools above each list to <strong>search</strong>, <strong>filter</strong>, <strong>group</strong> and <strong>choose columns</strong>. You can also <strong>save</strong> a set-up as a <strong>view</strong> so you can reuse it.</p><blockquote><p><strong>In simple words:</strong> Search finds a record, filters hide the ones you do not need, groups sort what is left into piles, and a saved view remembers your choices.</p></blockquote><h2 id="global-search" tabindex="-1">Global search <a class="header-anchor" href="#global-search" aria-label="Permalink to &quot;Global search&quot;">​</a></h2><p>The search in the top bar looks through the whole system at once. It works as a <strong>command palette</strong>: you can find pages, records and actions, and jump to them from the keyboard. Use it when you do not know which page holds what you need.</p><ol><li>Click the search box in the top bar, or press <strong>Ctrl+K</strong>.</li><li>Type a word, a name or a number. The box reads <strong>Search navigation, records and actions</strong>.</li><li>Pick a result to open it.</li></ol><p>Before you type, the palette lists the pages of each module, grouped under headings such as <strong>Dashboard</strong>, <strong>Contact</strong> and <strong>Sales</strong>. Use the keyboard shortcuts shown at the bottom of the window:</p><ul><li><strong>Up and down arrows:</strong> Move between results.</li><li><strong>Enter:</strong> Open the result.</li><li><strong>Ctrl+Enter:</strong> Open the result in a new tab.</li><li><strong>Ctrl+S:</strong> Pin the result so it stays easy to reach. You can also click the star next to it.</li><li><strong>Esc:</strong> Close the palette.</li></ul>',8)),s(o,{src:"/images1/getting-started/global_search.png",alt:"Global search window listing pages grouped by module with keyboard shortcuts"}),e[1]||(e[1]=t('<h2 id="the-list-toolbar" tabindex="-1">The list toolbar <a class="header-anchor" href="#the-list-toolbar" aria-label="Permalink to &quot;The list toolbar&quot;">​</a></h2><p>Every list page has the same tools. They sit above the table:</p><ul><li><strong><em>Tabs:</em></strong> Switch between views, for example <strong>Default</strong>, <strong>My Quotations</strong>, <strong>Quotations</strong>, <strong>Sales Orders</strong> and <strong>Archived</strong>. The three dots at the end of the tabs open the views menu.</li><li><strong><em>Group by:</em></strong> Groups the records. The second drop-down sets the order.</li><li><strong><em>Search:</em></strong> Searches inside this list only.</li><li><strong><em>Filters:</em></strong> The funnel icon. The small number on it shows how many filters are on.</li><li><strong><em>Columns:</em></strong> The column manager. Choose and arrange the columns.</li></ul>',3)),s(o,{src:"/images1/getting-started/table_toolbar.png",alt:"List toolbar with view tabs, Group by, Search, Filters and Columns"}),e[2]||(e[2]=t('<h2 id="search-in-a-list" tabindex="-1">Search in a list <a class="header-anchor" href="#search-in-a-list" aria-label="Permalink to &quot;Search in a list&quot;">​</a></h2><ol><li>Click the <strong>Search</strong> box above the list.</li><li>Type a word, a name or a number.</li></ol><p>The list updates and shows only the records that match. This search looks in the columns that the page makes searchable, such as <strong>Number</strong> or <strong>Customer</strong>. Clear the box to see all records again.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Sort the list by clicking a column title. Click it again to reverse the order.</p></div><h2 id="filters" tabindex="-1">Filters <a class="header-anchor" href="#filters" aria-label="Permalink to &quot;Filters&quot;">​</a></h2><p>Filters hide the records you do not need.</p><ol><li>Click the <strong>funnel icon</strong>. The <strong>Filters</strong> panel opens.</li><li>Click <strong>Add rule</strong>.</li><li>Choose a field from the list, such as <strong>Sales Person</strong>, <strong>Customer</strong> or <strong>Created At</strong>.</li><li>Set the condition, for example <strong>Contains</strong>, and choose the values.</li><li>Click <strong>Apply filters</strong>.</li></ol><p>The number on the funnel shows how many filters are on. Click <strong>Reset</strong> in the panel to clear them all. Next to each rule, use the copy icon to duplicate it and the bin icon to delete it.</p>',8)),s(o,{src:"/images1/getting-started/filter_add_rule.png",alt:"Filters panel with Add rule and the list of fields"}),e[3]||(e[3]=t("<p>The conditions depend on the field:</p><ul><li><strong>Text fields:</strong> for example contains or equals a word.</li><li><strong>Date fields:</strong> for example before, after or on a date.</li><li><strong>Related records:</strong> for example is one of the chosen customers.</li></ul><p>Add more rules to narrow the list further. Choose <strong>OR condition</strong> to match records that meet any of the rules, instead of all of them.</p>",3)),s(o,{src:"/images1/getting-started/filter_rule_set.png",alt:"Filters panel with a Payment Term rule, Add rule and Apply filters"}),e[4]||(e[4]=t('<h2 id="group-records" tabindex="-1">Group records <a class="header-anchor" href="#group-records" aria-label="Permalink to &quot;Group records&quot;">​</a></h2><p>Grouping puts records with the same value under one heading, so you can see how many fall in each group.</p><ol><li>Click the <strong>Group by</strong> drop-down and choose a field, such as <strong>Author</strong> or <strong>Medium</strong>.</li><li>In the second drop-down, choose <strong>Ascending</strong> or <strong>Descending</strong> to set the order of the groups.</li></ol><p>The list now shows a heading for each value, for example <strong>Author: Ava Lewis</strong>, with the matching records under it. To remove the grouping, clear the <strong>Group by</strong> field.</p>',4)),s(o,{src:"/images1/getting-started/group_by.png",alt:"Posts list grouped by Author"}),e[5]||(e[5]=t('<h2 id="column-manager" tabindex="-1">Column manager <a class="header-anchor" href="#column-manager" aria-label="Permalink to &quot;Column manager&quot;">​</a></h2><p>Use the column manager to choose which columns you see and in which order.</p><ol><li>Click the <strong>Columns</strong> icon.</li><li>Tick a column to show it. Untick a column to hide it.</li><li>Drag the handle at the right of a column name to move it up or down. The columns in the list follow the same order.</li><li>Click <strong>Reset</strong> to go back to the default columns.</li></ol>',3)),s(o,{src:"/images1/getting-started/column_manager.png",alt:"Column manager with tick boxes and drag handles"}),e[6]||(e[6]=t('<p>Your choice changes only how you see the list. The records are not changed.</p><h2 id="views" tabindex="-1">Views <a class="header-anchor" href="#views" aria-label="Permalink to &quot;Views&quot;">​</a></h2><p>A <strong>view</strong> is a saved set of search, filters and grouping. Use views for the lists you open every day.</p><h3 id="switch-between-views" tabindex="-1">Switch between views <a class="header-anchor" href="#switch-between-views" aria-label="Permalink to &quot;Switch between views&quot;">​</a></h3><p>Click a tab above the list to open that view. To see all views, click the three dots at the end of the tabs. The <strong>Views</strong> menu has <strong>Add New</strong> and <strong>Reset</strong> at the top, and lists the views below. It groups them as:</p><ul><li><strong><em>Favorite Views:</em></strong> The views that show as tabs.</li><li><strong><em>Saved Views:</em></strong> The views you or other users saved.</li><li><strong><em>Preset Views:</em></strong> The views that come with the page, such as <strong>Default</strong>.</li></ul><p>Click <strong>Reset</strong> to go back to the default view.</p>',7)),s(o,{src:"/images1/getting-started/views_menu.png",alt:"Views menu with Add New, Reset and Favorite Views"}),e[7]||(e[7]=t('<h3 id="save-a-view" tabindex="-1">Save a view <a class="header-anchor" href="#save-a-view" aria-label="Permalink to &quot;Save a view&quot;">​</a></h3><ol><li><p>Set up the list the way you want it, with the search, filters and grouping you need.</p></li><li><p>Click the three dots at the end of the tabs and choose <strong>Add New</strong>.</p></li><li><p>In the <strong>Save View</strong> window, fill in:</p><ul><li><strong><em>Name:</em></strong> The title of the view. This field is required.</li><li><strong><em>Icon:</em></strong> Pick an icon for the tab.</li><li><strong><em>Add To Favorites:</em></strong> Turn on to show the view as a tab.</li><li><strong><em>Make Public:</em></strong> Turn on to let all users use the view.</li></ul></li><li><p>Click <strong>Submit</strong>, or <strong>Cancel</strong> to close the window without saving.</p></li></ol>',2)),s(o,{src:"/images1/getting-started/save_view_modal.png",alt:"Save View window with Name, Icon, Add To Favorites and Make Public"}),e[8]||(e[8]=t('<h3 id="manage-a-view" tabindex="-1">Manage a view <a class="header-anchor" href="#manage-a-view" aria-label="Permalink to &quot;Manage a view&quot;">​</a></h3><p>Use the actions next to a view in the views menu to:</p><ul><li><strong><em>Apply View:</em></strong> Open the view.</li><li><strong><em>Add to Favorites</em> or <em>Remove from Favorites:</em></strong> Show or hide the view as a tab.</li><li><strong><em>Replace View:</em></strong> Overwrite the view with what is on screen now.</li><li><strong><em>Delete View:</em></strong> Remove the view.</li></ul><p>You can also edit a view to change its name, icon or visibility.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>A lock icon next to a view means you cannot change it. This is the case for preset views.</p></div><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./stages.html">Stages</a></li><li><a href="./activities.html">Activities</a></li></ul>',7))])}const _=r(l,[["render",h]]);export{w as __pageData,_ as default};
